66	    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;
67	
68	    #[derive_message_formats]
69	    fn message(&self) -> String {
70	        "Empty `finally` clause".to_string()
71	    }
72	
73	    fn fix_title(&self) -> Option<String> {
74	        Some("Remove the `finally` clause".to_string())
75	    }
76	}
