78	/// RUF072
79	pub(crate) fn useless_finally(checker: &Checker, try_stmt: &StmtTry) {
80	    let finalbody = &try_stmt.finalbody;
81	
82	    if !is_stub_body(finalbody) {
83	        return;
84	    }
85	
86	    let source = checker.source();
87	    let tokens = checker.tokens();
88	
89	    // `is_stub_body` guarantees at least one statement in finalbody
90	    let last_finalbody_stmt = finalbody.last().unwrap();
91	    let (preceding_end, preceding_stmt) = preceding_clause_info(try_stmt);
92	
93	    let Some(finally_start) = tokens
94	        .in_range(TextRange::new(preceding_end, last_finalbody_stmt.end()))
95	        .iter()
96	        .find(|token| token.kind() == TokenKind::Finally)
97	        .map(Ranged::start)
98	    else {
99	        return;
100	    };
101	
102	    let finally_range = TextRange::new(finally_start, last_finalbody_stmt.end());
103	
104	    let has_comments = finally_contains_comments(
105	        preceding_stmt,
106	        preceding_end,
107	        last_finalbody_stmt,
108	        finally_range,
109	        checker,
110	    );
111	
112	    let mut diagnostic = checker.report_diagnostic(UselessFinally, finally_range);
113	
114	    if has_comments {
115	        return;
116	    }
117	
118	    let is_bare_try_finally = try_stmt.handlers.is_empty() && try_stmt.orelse.is_empty();
119	
120	    if is_bare_try_finally {
121	        // bare `try/finally: pass` — unwrap the try body
122	        let (Some(first_body_stmt), Some(last_body_stmt)) =
123	            (try_stmt.body.first(), try_stmt.body.last())
124	        else {
125	            return;
126	        };
127	
128	        let try_indentation = indentation(source, try_stmt).unwrap_or_default();
129	
130	        let Ok(adjusted) = crate::fix::edits::adjust_indentation(
131	            TextRange::new(
132	                source.line_start(first_body_stmt.start()),
133	                source.full_line_end(last_body_stmt.end()),
134	            ),
135	            try_indentation,
136	            checker.locator(),
137	            checker.indexer(),
138	            checker.stylist(),
139	        ) else {
140	            return;
141	        };
142	
143	        let try_line_start = source.line_start(try_stmt.start());
144	        let finally_full_end = source.full_line_end(last_finalbody_stmt.end());
145	        let edit =
146	            Edit::range_replacement(adjusted, TextRange::new(try_line_start, finally_full_end));
147	        diagnostic.set_fix(Fix::safe_edit(edit));
148	    } else {
149	        // `try/except/finally: pass` — remove the finally clause
150	        let finally_line_start = source.line_start(finally_start);
151	        let finally_full_end = source.full_line_end(last_finalbody_stmt.end());
152	        let edit = Edit::range_deletion(TextRange::new(finally_line_start, finally_full_end));
153	        diagnostic.set_fix(Fix::safe_edit(edit));
154	    }
155	}
