157	/// Returns the end offset of the clause preceding `finally` and the last
158	/// statement in that clause's body (used for comment indentation checks)
159	fn preceding_clause_info(try_stmt: &StmtTry) -> (TextSize, Option<&Stmt>) {
160	    if let Some(last) = try_stmt.orelse.last() {
161	        return (last.end(), Some(last));
162	    }
163	    if let Some(handler) = try_stmt.handlers.last() {
164	        let last_stmt = handler.as_except_handler().and_then(|h| h.body.last());
165	        return (handler.end(), last_stmt);
166	    }
167	    match try_stmt.body.last() {
168	        Some(last) => (last.end(), Some(last)),
169	        None => (try_stmt.start(), None),
170	    }
171	}
