409	/// The range would be the entirety of `    print("Hello, world!")`.
410	pub(crate) fn adjust_indentation(
411	    range: TextRange,
412	    indentation: &str,
413	    locator: &Locator,
414	    indexer: &Indexer,
415	    stylist: &Stylist,
416	) -> Result<String> {
417	    let contents = locator.slice(range);
418	
419	    // If the range includes a multi-line string, use LibCST to ensure that we don't adjust the
420	    // whitespace _within_ the string.
421	    let contains_multiline_string = indexer.multiline_ranges().intersects(range)
422	        || indexer.interpolated_string_ranges().intersects(range);
423	
424	    // If the range has mixed indentation, we will use LibCST as well.
425	    let mixed_indentation = contents.universal_newlines().any(|line| {
426	        let trimmed = line.trim_whitespace_start();
427	        if trimmed.is_empty() {
428	            return false;
429	        }
430	
431	        let line_indentation: &str = &line[..line.len() - trimmed.len()];
432	        line_indentation.contains('\t') && line_indentation.contains(' ')
433	    });
434	
435	    // For simple cases, try to do a manual dedent.
436	    if !contains_multiline_string && !mixed_indentation {
437	        if let Some(dedent) = dedent_to(contents, indentation) {
438	            return Ok(dedent);
439	        }
440	    }
441	
442	    let module_text = format!("def f():{}{contents}", stylist.line_ending().as_str());
443	
444	    let mut tree = match_statement(&module_text)?;
445	
446	    let embedding = match_function_def(&mut tree)?;
447	
448	    let indented_block = match_indented_block(&mut embedding.body)?;
449	    indented_block.indent = Some(indentation);
450	
451	    let module_text = indented_block.codegen_stylist(stylist);
452	    let module_text = module_text
453	        .strip_prefix(stylist.line_ending().as_str())
454	        .unwrap()
455	        .to_string();
456	    Ok(module_text)
457	}
